mapper.select:
SELECT f.* FROM sensor_ingest_file f LEFT JOIN phm_device d ON d.id = f.device_id WHERE 1 = 1 AND f.id = #{id} AND f.status = #{status} AND f.source_type = #{sourceType}
AND (f.file_name LIKE CONCAT('%', #{keyword}, '%') OR f.device_code LIKE CONCAT('%', #{keyword}, '%') OR f.point_code LIKE CONCAT('%', #{keyword}, '%'))
AND (f.device_id IS NULL OR (1 = 1 ${params.dataScope})) ORDER BY f.id DESC
